 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Orchard Data Ltd."],
   "quote": "between Northwind Labs, Inc. (\"Northwind\") and Orchard Data Ltd. (\"Orchard\")"
  },
  "counterparty": {
   "value": "Orchard Data Ltd.",
   "quote": "Orchard Data Ltd. (\"Orchard\")"
  },
  "effective_date": {
   "value": "2025-11-24",
   "quote": "made effective November 24, 2025"
  },
  "term_months": {
   "value": 6,
   "quote": "The initial term of this Agreement is six months"
  },
  "auto_renewal": {
   "value": null,
   "quote": null
  },
  "renewal_notice_days": {
   "value": null,
   "quote": null
  },
  "governing_law": {
   "value": "Florida",
   "quote": "the laws of the State of Florida"
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": null,
   "quote": null
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": false,
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  "confidentiality_years": {
   "value": 5,
   "quote": "continue for a period of five years following termination of this Agreement"
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Imogen Carter",
   "email": "imogen.carter@orchard.example",
   "title": "Managing Director",
   "party": "Orchard Data Ltd."
  }
 ],
 "risks": [
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "Northwind cannot exit the NDA without cause. It can terminate only for an uncured material breach, so it stays bound for the full term and the post-termination confidentiality tail.",
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  {
   "id": "confidentiality_tail_after_termination",
   "severity": "low",
   "message": "Confidentiality obligations run five years after termination, with no carve-out for trade secrets that need longer protection and no definition of Confidential Information or its exclusions in the text.",
   "quote": "The Receiving Party's obligations under this Agreement continue for a period of five years following termination of this Agreement."
  },
  {
   "id": "non_solicitation_in_nda",
   "severity": "low",
   "message": "The NDA includes a non-solicitation covenant lasting the term plus twelve months, which restricts Northwind's hiring of Orchard personnel involved in the agreement.",
   "quote": "During the term and for twelve months thereafter, neither Party shall knowingly solicit for employment any Personnel of the other Party who were directly involved in the performance of this Agreement"
  },
  {
   "id": "audit_rights",
   "severity": "low",
   "message": "Each party may audit the other's records annually. This is unusual for an NDA and could expose Northwind's records to Orchard.",
   "quote": "a Party may audit the other Party's records solely to verify compliance with this Agreement"
  },
  {
   "id": "no_liability_cap_or_remedies_clause",
   "severity": "low",
   "message": "The agreement has no liability cap and no clear remedies clause, so exposure for a breach is not limited.",
   "quote": "either Party may pursue the remedies available to it"
  },
  {
   "id": "term_expired_ambiguity",
   "severity": "low",
   "message": "The six-month initial term from 2025-11-24 ended around 2026-05-24, and the document does not say what happens afterward (renewal or expiry), so the status of the NDA is unclear.",
   "quote": "The initial term of this Agreement is six months (the \"Initial Term\")."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a mutual NDA between Northwind Labs, Inc. and Orchard Data Ltd., effective November 24, 2025, with a six-month initial term and Florida governing law. It can be terminated only for uncured material breach, and confidentiality obligations last five years after termination."
}
